package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/** The sheet's late percent (two decimals, 0.00 until set). An overdue claim (OPEN, its due-by — its
 *  date plus the terms — before the sheet's today) gains the late percent of its figure for every full
 *  30 days it is overdue, rounded half to even to two decimals, on top. The charge is never bound by a
 *  statement; settling freezes it into the settled due. A correction (a negative amount) has no late charge. */
@Service
public class LatePct {

    public static final String KEY = "late-pct";

    public static final String DEFAULT = "0.00";

    private final SettingRepository settings;
    private final SheetClock clock;

    public LatePct(SettingRepository settings, SheetClock clock) {
        this.settings = settings;
        this.clock = clock;
    }

    /** The late charge as it stands on the sheet's today. */
    public Charge of(String sheetId) {
        return new Charge(new BigDecimal(settings.find(sheetId, KEY).orElse(DEFAULT)),
                Integer.parseInt(settings.find(sheetId, Terms.KEY).orElse(Terms.DEFAULT)), clock.today(sheetId));
    }

    /** The late percent, the terms and the day the charge is worked out on. */
    public record Charge(BigDecimal pct, int terms, LocalDate today) {

        /** The figure with the claim's late charge on top; null (n/a) stays null. */
        public BigDecimal addTo(Claim claim, BigDecimal figure) {
            if (figure == null || claim.getStatus() != ClaimStatus.OPEN || claim.isCorrection()) return figure;
            long late = ChronoUnit.DAYS.between(claim.getDate().plusDays(terms), today);
            if (late <= 0) return figure;
            long periods = late / 30;
            return figure.add(figure.multiply(pct).multiply(BigDecimal.valueOf(periods))
                    .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN));
        }
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Floor;
import net.officefloor.hq.app.setting.LatePct;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes a statement for the person: works out their due-total as the screen shows it, binds each of
 * their claims that counts (OPEN or SETTLED) to the figure it has now, unbinds the rest
 * (leaving a held person's OPEN claims, which count in no total, as they are), and moves
 * the person's statement count, last due-total and date (the sheet's today) on.
 *
 * A claim's figure is its settled due, else the figure a statement bound it to, else its live due at
 * the rate of the person's grade in force on its date (the grade in force on that date too), at least the sheet's floor (n/a without a rate). The due-total adds up the counting
 * claims' figures, each with its late charge on top (see {@link LatePct}; the bound figure leaves it out, so it
 * keeps following the sheet's today), skipping n/a; it is n/a when the grade in force on today has no rate there and no counting claim
 * has a figure.
 */
public class TakeStatement {
    public void take(@Val Person person, ClaimRepository claims, PersonRepository people, RateRepository rateRepository,
            SheetClock clock, Floor floor, LatePct latePct, Out<Statement> statementOut) {
        String sheetId = person.getSheetId();
        LocalDate today = clock.today(sheetId);
        List<Rate> rates = rateRepository.findBySheet(sheetId);
        BigDecimal least = floor.of(sheetId);
        LatePct.Charge late = latePct.of(sheetId);
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        boolean figured = false;
        int counted = 0;
        for (Claim claim : claims.findByPerson(sheetId, person.getId())) {
            boolean counts = claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
            if (counts && !person.counts(claim.getStatus())) {
                continue;           // a held person's OPEN claim: in no total, and left as it is
            } else if (!counts) {
                claim.setStated(false);
                claim.setStatedDue(null);
            } else {
                BigDecimal figure = figure(claim, person, rates, least);
                if (figure != null) figured = true;
                BigDecimal due = late.addTo(claim, figure);
                if (due != null) sum = sum.add(due);
                claim.setStated(true);
                claim.setStatedDue(figure);
                counted++;
            }
            claims.save(claim);
        }
        BigDecimal dueTotal = Rate.inForce(rates, person.gradeOn(today), today).isEmpty() && !figured ? null : sum;
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(dueTotal);
        person.setStatementDate(today);
        people.saveStatement(person);
        statementOut.set(new Statement(dueTotal, counted));
    }

    /** amount × pct / 100, rounded half to even to two decimals and at least the floor, unless already fixed; null when n/a. */
    private static BigDecimal figure(Claim claim, Person person, List<Rate> rates, BigDecimal least) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isStated()) return claim.getStatedDue();
        return Floor.raise(claim, Rate.inForce(rates, person.gradeOn(claim.getDate()), claim.getDate())
                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .orElse(null), least);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Floor;
import net.officefloor.hq.app.setting.LatePct;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Moves the claim to the action's status, refusing a change its current status does not allow.
 *  Opening gives the claim the sheet's next number, which it keeps when voided. Settling fixes the claim's
 *  due at the person's grade's rate in force on the claim's date (none when there is none, so it stays live).
 *  A claim a statement binds is settled at its bound figure. An overdue claim's late charge is frozen in on top.
 *  The user who opened a claim may not settle it (four eyes).
 *  Publishes the number the audit line carries. */
public class ApplyClaimAction {
    public void apply(@Val ClaimAction action, @Val Claim claim, ClaimRepository repository,
            PersonRepository people, RateRepository rates, Floor floor, LatePct latePct, Out<ClaimNumber> numberOut,
            @RequestParam(value = "user", required = false) String user)
            throws InvalidClaimStatusException {
        if (!action.allowedFrom(claim.getStatus())) {
            throw new InvalidClaimStatusException(
                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
        }
        if (action == ClaimAction.SETTLE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it.");
        }
        // The late charge is worked out while the claim is still OPEN, so settling freezes it in.
        BigDecimal settledDue = action != ClaimAction.SETTLE ? null : latePct.of(claim.getSheetId())
                .addTo(claim, claim.isStated() ? claim.getStatedDue() : dueNow(claim, people, rates, floor));
        claim.setStatus(action.to());
        switch (action) {
            case OPEN -> {
                claim.setNumber(repository.nextNumber(claim.getSheetId()));
                claim.setOpenedBy(user);
            }
            case SETTLE -> claim.setSettledDue(settledDue);
            default -> { }
        }
        numberOut.set(new ClaimNumber(claim.getNumber()));
    }

    /** amount × pct / 100, rounded half to even to two decimals and at least the floor; null when no rate is in force on the claim's date. */
    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates, Floor floor) {
        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
        return Floor.raise(claim, Rate.inForce(rates.findBySheet(claim.getSheetId()), person.gradeOn(claim.getDate()), claim.getDate())
                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .orElse(null), floor.of(claim.getSheetId()));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Floor;
import net.officefloor.hq.app.setting.LatePct;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, in the order
 * they were added, and the sheet's claimed-total and due-total.
 *
 * Only OPEN and SETTLED claims count, and a held person's OPEN claims do not. A claim's figure is its settled due, else the figure a statement
 * bound it to, else its live due at the person's grade's rate in force on its date, at least the sheet's floor
 * (n/a without a rate), plus the late charge of an overdue OPEN claim (see {@link LatePct}).
 * A person's due-total adds up their counting claims' figures, skipping n/a; it is n/a when the grade
 * in force on the sheet's today has no rate there and no counting claim has a figure. The sheet's due-total
 * adds up the people's due-totals, skipping n/a.
 */
@Service
public class Rollup {

    static final String NA = "n/a";

    /** One person's figures, as text with two decimals (due-total may be n/a). */
    public record Figures(String name, String claimed, String dueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
        }
    }

    /** The sheet's figures at one moment: people by id, in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
        boolean sameTotals(Snapshot other) {
            return claimedTotal.equals(other.claimedTotal) && dueTotal.equals(other.dueTotal);
        }
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetClock clock;
    private final Floor floor;
    private final LatePct latePct;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetClock clock, Floor floor,
            LatePct latePct) {
        this.floor = floor;
        this.latePct = latePct;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.clock = clock;
    }

    public Snapshot take(String sheetId) {
        LocalDate today = clock.today(sheetId);
        List<Rate> sheetRates = rates.findBySheet(sheetId);
        List<Claim> sheetClaims = claims.findBySheet(sheetId);
        BigDecimal least = floor.of(sheetId);
        LatePct.Charge late = latePct.of(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        BigDecimal dueTotal = zero();
        for (Person person : people.findBySheet(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            boolean figured = false;
            for (Claim claim : sheetClaims) {
                if (claim.getPersonId() != person.getId()) continue;
                if (!person.counts(claim.getStatus())) continue;
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = late.addTo(claim, figure(claim, person, sheetRates, least));
                if (figure != null) {
                    due = due.add(figure);
                    figured = true;
                }
            }
