511	// The sheet's rates for each grade: a percent with two decimals, set here, each in force from its
512	// from-date (null: from the beginning of time). A claim uses its grade's rate in force on its date;
513	// with none it shows n/a, and so does anything due that depends on it. Money and percents come from
514	// the server as strings with two decimals and are worked in whole cents and hundredths of a percent,
515	// never floats.
516	export type Rate = { grade: string; pct: string; from: string | null };
