534	/** The grade's percent in force on the date (yyyy-MM-dd): the rate with the latest from-date on or
535	 *  before it. Undefined when no rate is in force then, or the date is not known yet. */
536	export function rateOn(rates: Rate[], grade: string, date: string | undefined): string | undefined {
537	  if (date === undefined) return undefined;
538	  let best: Rate | undefined;
539	  for (const r of rates) {
540	    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
541	    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
542	  }
543	  return best?.pct;
544	}
