546	/** A two-decimal string (a correction's is negative) as a whole number of hundredths. */
547	export const toHundredths = (value: string): bigint => {
548	  const negative = value.startsWith('-');
549	  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
550	  const h = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0') || '0');
551	  return negative ? -h : h;
552	};
