554	/** Hundredths as a two-decimal string, with a minus sign when negative. */
555	export const fromHundredths = (h: bigint): string => {
556	  const abs = h < 0n ? -h : h;
557	  return `${h < 0n ? '-' : ''}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
558	};
