560	/** amount × pct / 100, rounded half to even to two decimals; n/a without a rate. A correction's negative
561	 *  amount rounds like any other, by its size, keeping its sign. */
562	export function due(amount: string, pct: string | undefined): string {
563	  if (pct === undefined) return NA;
564	  // cents × hundredths-of-a-percent gives cents × 10000.
565	  const signed = toHundredths(amount) * toHundredths(pct);
566	  const scaled = signed < 0n ? -signed : signed;
567	  const cents = scaled / 10000n;
568	  const rest = scaled % 10000n;
569	  const rounded = rest > 5000n || (rest === 5000n && cents % 2n === 1n) ? cents + 1n : cents;
570	  return fromHundredths(signed < 0n ? -rounded : rounded);
571	}
