import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, postJson, putJson } from '../../api/http';
import { useSingleSubmit } from '../../api/useSingleSubmit';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import { useCurrentUser } from '../session/SignIn';
import { useSheetToday } from '../sheet/SheetToday';
import { NA, due, fromHundredths, toHundredths } from '../rates/Rates';
import { useFloor, useLatePct, useTerms } from '../settings/Settings';
import { periodOf, usePeriods } from '../periods/usePeriods';

// A person's claims, listed under their row newest first. One form per row adds a claim, or edits
// the claim whose editor is open (URL state `editClaim`, the claim's id). Amounts come from the
// server as strings with two decimals and are added up in whole cents, never as floats. A claim's
// status moves DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN -> VOID; the server refuses any other change.
// Opening gives a claim the sheet's next number, which a voided claim keeps; a draft has none.
// Only a draft can be edited: to change an open claim, void it and add a new one.
// The user who opens a claim is recorded and may not settle it.
// Settling fixes a claim's due at the rate of that moment. A person's statement binds each of their
// counting claims to the figure it has then, until their next statement; every other claim's due
// follows the current rate. Each claim shows the period its date falls in, if any.
// A claim with a negative amount is a correction: the form must name, by number, a SETTLED claim of the
// same person that it corrects (the server refuses it otherwise). Its due has no floor and no late charge.
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when the claim is opened, and kept if it is voided; null for a draft. */
  number: number | null;
  /** The due fixed when the claim was settled; null while it is live (not settled, or settled without a rate). */
  settledDue: string | null;
  /** The user who opened the claim; null until it is opened. That user may not settle it. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim to `statedDue`. */
  stated: boolean;
  /** The figure the last statement bound the claim to; null when unbound, or bound without a rate (n/a). */
  statedDue: string | null;
  /** The number of the SETTLED claim this correction (a negative amount) corrects; null for any other claim. */
  corrects: number | null };

const ACTIONS = [
  { action: 'open', label: 'Open' },
  { action: 'settle', label: 'Settle' },
  { action: 'void', label: 'Void' },
];

type ClaimBody = { amount: string; date: string; note: string; corrects: string };

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'];
const sheetPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;

export function useClaims(sheet: string): Claim[] {
  return (
    useQuery({
      queryKey: claimsKey(sheet),
      queryFn: () => getJson<Claim[]>(`${sheetPath(sheet)}/claims`),
      enabled: !!sheet,
    }).data ?? []
  );
}

/** Only OPEN and SETTLED claims count toward claimed, due-total and every total; the OPEN claims of a
 *  person on hold (`held`) count in none. */
export const counts = (c: Claim, held = false) => c.status === 'SETTLED' || (c.status === 'OPEN' && !held);

/** What the late charge is worked out from: the sheet's late percent, terms and today. */
export type Late = { pct: string; terms: number; today: string | undefined };

export function useLate(sheet: string): Late {
  return { pct: useLatePct(sheet), terms: useTerms(sheet), today: useSheetToday(sheet) };
}

/** A claim's due: the due fixed when it was settled (any late charge frozen in), else the figure a
 *  statement bound it to, else its live due at `pct`, at least the sheet's `floor` (n/a without a rate);
 *  an overdue claim's late charge goes on top of the bound or live figure. A correction has no floor and no late charge. */
export const claimDue = (c: Claim, pct: string | undefined, floor: string, late: Late): string =>
  c.settledDue ?? lateCharge(c, c.stated ? c.statedDue ?? NA : atLeast(due(c.amount, pct), c.corrects === null ? floor : undefined), late);

/** The figure plus the late percent of it for every full 30 days the claim is overdue, rounded half to
 *  even to two decimals. A statement never binds the charge: it follows the sheet's today. */
function lateCharge(c: Claim, figure: string, late: Late): string {
  if (figure === NA || c.corrects !== null || !isOverdue(c, late.terms, late.today)) return figure;
  const days = (Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${dueBy(c, late.terms)}T00:00:00Z`)) / 86_400_000;
  const periods = BigInt(Math.floor(days / 30));
  return fromHundredths(toHundredths(figure) + roundedCharge(toHundredths(figure) * toHundredths(late.pct) * periods));
}

/** cents × hundredths-of-a-percent (× 10000) to cents, rounded half to even. */
function roundedCharge(scaled: bigint): bigint {
  const cents = scaled / 10000n;
  const rest = scaled % 10000n;
  return rest > 5000n || (rest === 5000n && cents % 2n === 1n) ? cents + 1n : cents;
}

/** The value raised to the floor; no floor (a correction's) leaves it as it is. */
const atLeast = (value: string, floor: string | undefined) =>
  floor !== undefined && value !== NA && toHundredths(value) < toHundredths(floor) ? floor : value;

/** Whether the claim keeps a figure of its own, whatever the rates: settled, or bound by a statement. */
export const hasFixedDue = (c: Claim) => c.settledDue !== null || (c.stated && c.statedDue !== null);

/** The claim's due-by (yyyy-MM-dd): its date plus the sheet's `terms` in days. */
export function dueBy(c: Claim, terms: number): string {
  const d = new Date(`${c.date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + terms);
  return d.toISOString().slice(0, 10);
}

/** Whether the claim is overdue: OPEN, with its due-by before the sheet's `today`. */
export const isOverdue = (c: Claim, terms: number, today: string | undefined) =>
  c.status === 'OPEN' && !!today && dueBy(c, terms) < today;

/** The counted claims' amounts added up, with two decimals; `held` says whose person is on hold. */
export function claimed(claims: Claim[], held: (personId: number) => boolean = () => false): string {
  return fromHundredths(claims.filter((c) => counts(c, held(c.personId))).reduce((sum, c) => sum + toHundredths(c.amount), 0n));
}

export function ClaimedTotal({ sheet, held }: { sheet: string; held: (personId: number) => boolean }) {
  const claims = useClaims(sheet);
  return (
    <p>
      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims, held)}</strong>
    </p>
  );
}

/** The claims cell of a person's row: the claim form and the person's claims, newest first, each
 *  with its due at the person's grade's rate in force on its date (`pctOn`, undefined when none is). */
export function PersonClaims({ sheet, personId, claims, pctOn }: {
  sheet: string; personId: number; claims: Claim[]; pctOn: (date: string) => string | undefined;
}) {
  const [editId, setEditId] = useSearchParam('editClaim', asNumber);
  const editing = claims.find((c) => c.id === editId);

  return (
    <>
      {/* Keyed so opening another claim's editor (or closing it) refills the form. */}
      <ClaimForm key={editing ? `edit-${editing.id}` : 'add'} sheet={sheet} personId={personId}
        editing={editing} onDone={() => setEditId(undefined)} />
      <ul>
        {claims.map((c) => (
          <ClaimRow key={c.id} sheet={sheet} claim={c} pct={pctOn(c.date)} onEdit={() => setEditId(c.id)} />
        ))}
      </ul>
    </>
  );
}

/** One claim: its fields, status and due, with its edit and status buttons. A refused status change,
 *  or editing a claim that is not a draft or is dated in a closed period, shows the row's error, which
 *  the row's next action clears. */
function ClaimRow({ sheet, claim: c, pct, onEdit }: {
  sheet: string; claim: Claim; pct: string | undefined; onEdit: () => void;
}) {
  const queryClient = useQueryClient();
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const period = periodOf(usePeriods(sheet), c.date);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const { terms, today } = late;
  const change = useMutation({
    mutationFn: (action: string) => postJson<Claim>(`${sheetPath(sheet)}/claims/${c.id}/${action}${by}`, {}),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
  });
  // Why the last press of Edit was refused; null when it was not.
  const [editRefused, setEditRefused] = useState<string | null>(null);

  return (
    <li data-testid={`claim-row-${c.id}`}>
      #<span data-testid="claim-number">{c.number ?? ''}</span>{' '}
      <span data-testid="claim-amount">{c.amount}</span>{' '}
      <span data-testid="claim-date">{c.date}</span>{' '}
      Period <span data-testid="claim-period">{period?.name ?? ''}</span>{' '}
      <span data-testid="claim-note">{c.note}</span>{' '}
      <span data-testid="claim-status">{c.status}</span>{' '}
      Opened by <span data-testid="claim-opened-by">{c.openedBy ?? ''}</span>{' '}
      Due <span data-testid="claim-due">{claimDue(c, pct, floor, late)}</span>{' '}
      Due by <span data-testid="claim-due-by">{dueBy(c, terms)}</span>{' '}
      Overdue <span data-testid="claim-overdue">{isOverdue(c, terms, today) ? 'yes' : 'no'}</span>{' '}
      Stated <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
      Corrects <span data-testid="claim-corrects">{c.corrects ?? ''}</span>{' '}
      <button type="button" data-testid="claim-edit" onClick={() => {
        change.reset();
        // Only a draft dated outside every closed period can be edited (the server refuses the rest).
        const refused = c.status !== 'DRAFT'
          ? `Only a draft claim can be edited; this one is ${c.status}. To change it, void it and add a new one.`
          : period?.closed ? `The claim is dated in the closed period ${period.name}; it cannot be edited.` : null;
        setEditRefused(refused);
        if (!refused) onEdit();
      }}>
        Edit
      </button>
      {ACTIONS.map(({ action, label }) => (
        <button key={action} type="button" data-testid={`claim-${action}`} disabled={change.isPending}
          onClick={() => { change.reset(); setEditRefused(null); change.mutate(action); }}>
          {label}
        </button>
      ))}
      {(change.isError || editRefused) && (
        <span role="alert" data-testid="claim-error">
          {' '}
          {editRefused
            ?? ((change.error instanceof HttpError && change.error.reason) || 'The claim could not be changed.')}
        </span>
      )}
    </li>
  );
}

function ClaimForm({ sheet, personId, editing, onDone }: {
  sheet: string; personId: number; editing?: Claim; onDone: () => void;
}) {
  const queryClient = useQueryClient();
  const today = useSheetToday(sheet);
  const [amount, setAmount] = useState(editing?.amount ?? '');
  // Undefined until changed: the sheet's today, which the server fills in when the date is blank.
  const [date, setDate] = useState<string | undefined>(editing?.date);
  const [note, setNote] = useState(editing?.note ?? '');
  // The number of the settled claim a correction (a negative amount) corrects; blank for any other claim.
  const [corrects, setCorrects] = useState(editing?.corrects?.toString() ?? '');
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const submitOnce = useSingleSubmit();
  const save = useMutation({
    mutationFn: (body: ClaimBody) =>
      editing
        ? putJson<Claim>(`${sheetPath(sheet)}/claims/${editing.id}${by}`, body)
        : postJson<Claim>(`${sheetPath(sheet)}/people/${personId}/claims${by}`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      if (editing) {
        onDone();
      } else {
        setAmount('');
        setDate(undefined);
        setNote('');
        setCorrects('');
      }
    },
  });
  const changed = <T,>(set: (v: T) => void) => (v: T) => {
    save.reset();
    set(v);
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          save.reset();
          // A missing or over-precise amount, or a correction not naming a settled claim of the person,
          // is refused by the server (400).
          return save.mutateAsync({ amount, date: date ?? '', note, corrects });
        });
      }}
    >
      <input data-testid="claim-form-amount" placeholder="Amount" inputMode="decimal" value={amount}
        onChange={(e) => changed(setAmount)(e.target.value)} />{' '}
      <input type="date" data-testid="claim-form-date" value={date ?? today ?? ''}
        onChange={(e) => changed(setDate)(e.target.value)} />{' '}
      <input data-testid="claim-form-note" placeholder="Note" value={note}
        onChange={(e) => changed(setNote)(e.target.value)} />{' '}
      <input data-testid="claim-form-corrects" placeholder="Corrects claim #" inputMode="numeric" value={corrects}
        onChange={(e) => changed(setCorrects)(e.target.value)} />{' '}
      <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
        {editing ? 'Save claim' : 'Add claim'}
      </button>
      {editing && (
        <button type="button" onClick={onDone}>
          Cancel
        </button>
      )}
      {save.isError && (
        <span role="alert" data-testid="claim-form-error">
          {' '}
          {(save.error instanceof HttpError && (save.error.status === 400 || save.error.status === 409) && save.error.reason)
            || 'The claim could not be saved.'}
        </span>
      )}
    </form>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, putJson } from '../../api/http';
import { useSingleSubmit } from '../../api/useSingleSubmit';
import { useCurrentUser } from '../session/SignIn';

// The sheet's settings and roles. The clerk limit (two decimals; blank: no limit) is the highest due
// a clerk may settle; a steward settles anything. Every user name is a clerk unless assigned steward
// here. The server enforces both when a claim is settled. The floor (two decimals, 1.00 until set) is
// the least live due a claim has; see `claimDue`. The terms (whole days, 14 until set) are how long
// after its date a claim is due by; see `dueBy`. The late percent (two decimals, 0.00 until set) is
// charged on an overdue claim's figure for every full 30 days it is overdue; see `lateCharge`.
type Setting = { key: string; value: string };
type Role = { user: string; role: string };

const SETTINGS = [{ key: 'clerk-limit', label: 'Clerk limit' }, { key: 'floor', label: 'Floor' },
  { key: 'terms', label: 'Terms (days)' }, { key: 'late-pct', label: 'Late %' }];

const DEFAULT_FLOOR = '1.00';

const DEFAULT_TERMS = '14';

const DEFAULT_LATE_PCT = '0.00';

const settingsKey = (sheet: string) => ['sheet', sheet, 'settings'];
const settingsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/settings`;
const rolesKey = (sheet: string) => ['sheet', sheet, 'roles'];
const rolesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/roles`;

function useSettings(sheet: string): Setting[] {
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Setting[]>(settingsPath(sheet)),
    enabled: !!sheet,
  }).data ?? [];
}

/** The sheet's floor: the least live due a claim has, with two decimals. */
export function useFloor(sheet: string): string {
  return useSettings(sheet).find((s) => s.key === 'floor')?.value || DEFAULT_FLOOR;
}

/** The sheet's terms: how many days after its date a claim is due by. */
export function useTerms(sheet: string): number {
  return Number(useSettings(sheet).find((s) => s.key === 'terms')?.value || DEFAULT_TERMS);
}

/** The sheet's late percent, with two decimals. */
export function useLatePct(sheet: string): string {
  return useSettings(sheet).find((s) => s.key === 'late-pct')?.value || DEFAULT_LATE_PCT;
}

export function Settings({ sheet }: { sheet: string }) {
  return (
    <section>
      <h2>Settings</h2>
      <SettingsForm sheet={sheet} />
      <Roles sheet={sheet} />
    </section>
  );
}

function SettingsForm({ sheet }: { sheet: string }) {
  const queryClient = useQueryClient();
  const current = useSettings(sheet);
  const [draft, setDraft] = useState<Record<string, string>>({});
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const submitOnce = useSingleSubmit();
  // Only the settings changed in the form are saved; each is written (and audited) on its own.
  const save = useMutation({
    mutationFn: async (changes: Record<string, string>) => {
      for (const [key, value] of Object.entries(changes)) {
        await putJson<Setting>(`${settingsPath(sheet)}/${encodeURIComponent(key)}${by}`, { value });
      }
    },
    onSuccess: () => setDraft({}),
    onSettled: () => queryClient.invalidateQueries({ queryKey: settingsKey(sheet) }),
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          save.reset();
          // A value that is not blank or an amount with up to two decimals is refused by the server (400);
          // the floor may not be blank.
          return save.mutateAsync(Object.fromEntries(Object.entries(draft).map(([k, v]) => [k, v.trim()])));
        });
      }}
    >
      {SETTINGS.map(({ key, label }) => (
        <span key={key}>
          <label>
            {label}{' '}
            <input
              data-testid={`setting-${key}`}
              inputMode="decimal"
              value={draft[key] ?? ''}
              onChange={(e) => {
                save.reset();
                setDraft((d) => ({ ...d, [key]: e.target.value }));
              }}
              // Deleting in the (empty) field also marks the setting as changed, so it can be cleared.
              onKeyDown={(e) => {
                if (e.key !== 'Delete' && e.key !== 'Backspace') return;
                const value = e.currentTarget.value;
                save.reset();
                setDraft((d) => (key in d ? d : { ...d, [key]: value }));
              }}
            />
          </label>{' '}
          (now: <strong data-testid={`setting-${key}-current`}>{current.find((s) => s.key === key)?.value ?? ''}</strong>){' '}
        </span>
      ))}
      <button type="submit" data-testid="settings-save" disabled={save.isPending}>
        Save settings
      </button>
      {save.isError && (
        <span role="alert" data-testid="settings-error">
          {' '}
          {(save.error instanceof HttpError && save.error.status === 400 && save.error.reason)
            || 'The settings could not be saved.'}
        </span>
      )}
    </form>
  );
}

function Roles({ sheet }: { sheet: string }) {
  const queryClient = useQueryClient();
  const roles = useQuery({
    queryKey: rolesKey(sheet),
    queryFn: () => getJson<Role[]>(rolesPath(sheet)),
    enabled: !!sheet,
  }).data ?? [];
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const submitOnce = useSingleSubmit();
  const save = useMutation({
    mutationFn: (body: Role) =>
      putJson<Role>(`${rolesPath(sheet)}/${encodeURIComponent(body.user)}${by}`, { role: body.role }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: rolesKey(sheet) });
      setName('');
      setRole('');
    },
  });

  return (
    <>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            // A blank name or a role other than clerk or steward is refused by the server (400).
            return save.mutateAsync({ user: name.trim(), role: role.trim() });
          });
        }}
      >
        <label>
          User{' '}
          <input
            data-testid="role-form-user"
            value={name}
            onChange={(e) => {
              save.reset();
              setName(e.target.value);
            }}
          />
        </label>{' '}
        <label>
          Role{' '}
          <input
            data-testid="role-form-role"
            list="role-options"
            value={role}
            onChange={(e) => {
              save.reset();
              setRole(e.target.value);
            }}
          />
          <datalist id="role-options">
            <option value="clerk" />
            <option value="steward" />
          </datalist>
        </label>{' '}
        <button type="submit" data-testid="role-form-submit" disabled={save.isPending}>
          Set role
        </button>
        {save.isError && (
          <span role="alert" data-testid="role-form-error">
            {' '}
            {(save.error instanceof HttpError && save.error.status === 400 && save.error.reason)
              || 'The role could not be saved.'}
          </span>
        )}
      </form>
      <table>
        <thead>
          <tr>
            <th>User</th>
            <th>Role</th>
          </tr>
        </thead>
        <tbody>
          {roles.map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td>{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, putJson } from '../../api/http';
import { useSingleSubmit } from '../../api/useSingleSubmit';
import { useCurrentUser } from '../session/SignIn';
import { useSheetToday } from '../sheet/SheetToday';

// The sheet's rates for each grade: a percent with two decimals, set here, each in force from its
// from-date (null: from the beginning of time). A claim uses its grade's rate in force on its date;
// with none it shows n/a, and so does anything due that depends on it. Money and percents come from
// the server as strings with two decimals and are worked in whole cents and hundredths of a percent,
// never floats.
export type Rate = { grade: string; pct: string; from: string | null };

const GRADES = ['A', 'B', 'C'];
export const NA = 'n/a';

export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'];
const ratesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;

export function useRates(sheet: string): Rate[] {
  return (
    useQuery({
      queryKey: ratesKey(sheet),
      queryFn: () => getJson<Rate[]>(ratesPath(sheet)),
      enabled: !!sheet,
    }).data ?? []
  );
}

/** The grade's percent in force on the date (yyyy-MM-dd): the rate with the latest from-date on or
 *  before it. Undefined when no rate is in force then, or the date is not known yet. */
export function rateOn(rates: Rate[], grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let best: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best?.pct;
}

/** A two-decimal string (a correction's is negative) as a whole number of hundredths. */
export const toHundredths = (value: string): bigint => {
  const negative = value.startsWith('-');
  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
  const h = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0') || '0');
  return negative ? -h : h;
};

/** Hundredths as a two-decimal string, with a minus sign when negative. */
export const fromHundredths = (h: bigint): string => {
  const abs = h < 0n ? -h : h;
  return `${h < 0n ? '-' : ''}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
};

/** amount × pct / 100, rounded half to even to two decimals; n/a without a rate. A correction's negative
 *  amount rounds like any other, by its size, keeping its sign. */
export function due(amount: string, pct: string | undefined): string {
  if (pct === undefined) return NA;
  // cents × hundredths-of-a-percent gives cents × 10000.
  const signed = toHundredths(amount) * toHundredths(pct);
  const scaled = signed < 0n ? -signed : signed;
  const cents = scaled / 10000n;
  const rest = scaled % 10000n;
  const rounded = rest > 5000n || (rest === 5000n && cents % 2n === 1n) ? cents + 1n : cents;
  return fromHundredths(signed < 0n ? -rounded : rounded);
}

/** Two-decimal values added up, skipping n/a. */
export function total(values: string[]): string {
  return fromHundredths(values.filter((v) => v !== NA).reduce((sum, v) => sum + toHundredths(v), 0n));
}

export function Rates({ sheet }: { sheet: string }) {
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  return (
    <section>
      <h2>Rates</h2>
      <RateForm sheet={sheet} />
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate % today</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateOn(rates, g, today) ?? NA}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>Rate %</th>
          </tr>
        </thead>
        <tbody>
          {rates.map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td>{r.from ?? 'start'}</td>
              <td data-testid="rate-pct">{r.pct}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

function RateForm({ sheet }: { sheet: string }) {
  return (
    useQuery({
      queryKey: peopleKey(sheet),
      queryFn: () => getJson<Person[]>(peoplePath(sheet)),
      enabled: !!sheet,
    }).data ?? []
  );
}

function useEditPerson() {
  return useSearchParam('editPerson', asNumber);
}

function useShowRetired() {
  return useSearchParam('showRetired', asFlag);
}

/** The "show retired" toggle: off when the screen is first opened, left as it is by loading a sheet. */
function ShowRetired() {
  const [show, setShow] = useShowRetired();
  return (
    <label>
      <input type="checkbox" data-testid="show-retired" checked={show}
        onChange={(e) => setShow(e.target.checked || undefined)} />{' '}
      Show retired
    </label>
  );
}

/** A person's due-total is the sum of their counted claims' already-rounded figures (0.00 with none).
 *  It is n/a when the grade in force on the sheet's today has no rate there, unless a counted claim has
 *  a figure (settled, bound by a statement, or at the grade in force on its date): then it is the sum
 *  of the figures there are. */
export function useDueTotalOf(sheet: string): (p: Person) => string {
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  return (p: Person) => {
    const dues = claims.filter((c) => c.personId === p.id && counts(c, p.held))
      .map((c) => claimDue(c, rateOn(rates, gradeOn(p, c.date), c.date), floor, late));
    if (rateOn(rates, gradeOn(p, today), today) === undefined && dues.every((d) => d === NA)) return NA;
    return total(dues);
  };
}

